import{_ as n,C as t,o,c as s,E as i,a2 as d}from"./chunks/framework.Cc8dJFaW.js";const y=JSON.parse('{"title":"Versioned Shared Memory Still Needs Action Authorization","description":"","frontmatter":{"title":"Versioned Shared Memory Still Needs Action Authorization","article_type":"engineering-insight","edition":"research-center","research_question":"版本化共享记忆能说明什么，写入范围与动作许可还需要哪些证据？","summary":"Current and legacy storage contracts plus five ledger controls separate visibility, attribution, key scope and authorized intent. Detection results cannot be converted directly into pre-effect prevention.","sources":"Same-day verified shared-memory documentation, provenance research and internal synthetic ledger experiment","date":"2026-11-18","column":"digital-employee","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261118-003","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-18-sig-20261118-003-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/digital-employee/2026-11-18-sig-20261118-003.md","filePath":"en/digital-employee/2026-11-18-sig-20261118-003.md","lastUpdated":null}'),c={name:"en/digital-employee/2026-11-18-sig-20261118-003.md"};function l(h,e,p,u,m,g){const a=t("ArticleCover"),r=t("ArticleTableScroll");return o(),s("div",null,[i(a,{image:"/assets/covers/daily-2026-11-18-sig-20261118-003-cover.png",kicker:"Research",title:"Versioned Shared Memory Still Needs Action Authorization",summary:"Current and legacy storage contracts plus five ledger controls separate visibility, attribution, key scope and authorized intent. Detection results cannot be converted directly into pre-effect prevention.",version:"2026-11-18",languageHref:"/zh/digital-employee/2026-11-18-sig-20261118-003",languageLabel:"中文"}),i(r,{language:"en"}),e[0]||(e[0]=d('<h1 id="versioned-shared-memory-still-needs-action-authorization" tabindex="-1">Versioned Shared Memory Still Needs Action Authorization <a class="header-anchor" href="#versioned-shared-memory-still-needs-action-authorization" aria-label="Permalink to &quot;Versioned Shared Memory Still Needs Action Authorization&quot;">​</a></h1><p>A plan URL has a complete edit history and a registered author. Does that authorize executing it? Our synthetic ledger controls expose two different possibilities: the registered author can write outside their allowed scope, or write a hostile value inside it. <strong>Version history supplies attribution evidence; it cannot own action authorization by itself.</strong> Engineers migrating shared memory should check visibility, authorship, write scope and permitted action separately.</p><h2 id="first-establish-which-state-was-read" tabindex="-1">First establish which state was read <a class="header-anchor" href="#first-establish-which-state-was-read" aria-label="Permalink to &quot;First establish which state was read&quot;">​</a></h2><p>Letta’s current shared-memory documentation describes repositories with per-agent checkouts. A writer commits and pushes changes with Git; other agents pull those commits. Initial attachment clones a repository, while later synchronization fast-forwards the local checkout. This establishes a documented visibility contract: shared repositories do not imply that every checkout sees identical content immediately. <a href="https://docs.letta.com/concepts/shared-memory" target="_blank" rel="noreferrer">Current documentation</a></p><p>The legacy memory-block interface has different semantics. Its read-only setting applies to a whole block, rather than independently to each attached agent. Its concurrency guidance warns that full rewrites can lose updates under last-writer-wins behavior and recommends one heavy-edit owner with append-only contributions from others. These are vendor-documented behaviors, not races reproduced here. <a href="https://docs.letta.com/guides/agents/multi-agent-shared-memory/" target="_blank" rel="noreferrer">Legacy block documentation</a></p><p>A migration therefore changes more than a storage noun. Immediate shared-state expectations and block-wide read-only settings differ from commit, push and pull responsibilities. Repository history, however, does not automatically determine who may modify a business key or whether a value may drive a consequential action. Repository or server controls may add permissions; absence from the inspected documentation cannot establish absence of enforcement.</p><h2 id="five-ledgers-separate-attribution-from-intent" tabindex="-1">Five ledgers separate attribution from intent <a class="header-anchor" href="#five-ledgers-separate-attribution-from-intent" aria-label="Permalink to &quot;Five ledgers separate attribution from intent&quot;">​</a></h2><p>ErosionBench, from a separate research team, constructs synthetic ledger scenarios by fixing authorized intent, consequential tools and safe arguments before rendering narrative trajectories. Its provenance definition examines whether action parameters derive from unregistered sources or writes outside permitted key prefixes. This is a diagnostic rule with a defined object of examination. <a href="https://arxiv.org/html/2611.11266v1" target="_blank" rel="noreferrer">Paper v1, sections 3–4</a></p><p>The same-day internal experiment constructed five ledgers from that prose definition. It executed neither the upstream monitor nor a Letta server. Choosing the latest matching attribution, requiring nonempty action arguments and preserving unknown when history is missing are our model choices. The Causal Influence Index, or CII, values below preserve the experiment’s inspectable output: zero means this rule found no source-registration or prefix violation.</p><table tabindex="0"><thead><tr><th>Constructed case</th><th>Attribution and scope</th><th>Internal model output</th><th>What the control separates</th></tr></thead><tbody><tr><td>Authorized plan value</td><td>Planner writes plan scope</td><td>0</td><td>Source and scope satisfy the model</td></tr><tr><td>Unregistered writer</td><td>Outsider writes plan scope</td><td>1</td><td>Writer identity is ineligible</td></tr><tr><td>Registered writer, wrong scope</td><td>Planner writes approval scope</td><td>1</td><td>Registered identity does not authorize every key</td></tr><tr><td>Hostile value in permitted scope</td><td>Planner writes a hostile plan URL</td><td>0</td><td>Eligible source and scope do not examine authorized intent</td></tr><tr><td>Missing history</td><td>No available attribution</td><td>Unknown</td><td>Missing evidence is not imputed as zero</td></tr></tbody></table><p>Source: five same-day internal synthetic controls. The <a href="/joinwell52/assets/evidence/2026-11-18-sig-20261118-003/experiment-003.json">experiment record</a> contains inputs, method, outputs and limits. These are not product attack-success rates.</p><p>The fourth row is particularly easy to overread. A zero from this rule does not establish that the complete auditor misses the attack. The paper treats provenance validity as diagnostic; a separate semantic monitor may still identify hostile content. The third row shows the converse problem with checking registered identity alone: existence in a registry and permission over a particular key are different conditions.</p><h2 id="detecting-an-attack-is-not-stopping-its-effect" tabindex="-1">Detecting an attack is not stopping its effect <a class="header-anchor" href="#detecting-an-attack-is-not-stopping-its-effect" aria-label="Permalink to &quot;Detecting an attack is not stopping its effect&quot;">​</a></h2><p>For clean-control evaluation under a fixed configuration, the authors report detecting 446 of 453 malicious scenarios and flagging 13 of 453 benign scenarios. Those are source-reported detection results, not our independent replication. They do not establish that 98.5% of effects were prevented before execution. <a href="https://arxiv.org/html/2611.11266v1" target="_blank" rel="noreferrer">Paper Table 3b</a></p><p>The main text describes one action-edge check as pre-execution and other provenance and semantic analysis as post-execution detection and localization. Appendices describe additional conjunctive veto routing. The admitted materials do not resolve that difference. Which exact paths can veto before execution remains open; combining the passages would not produce a verified prevention system.</p><p>Calibration has a related boundary. The paper explicitly withholds a finite-sample false-positive-rate guarantee because scores can tie at the threshold. A separate internal calculation uses entirely tied synthetic scores to show that the same threshold flags every value with greater-than-or-equal and none with strict greater-than. This illustrates comparator sensitivity. It is neither a measured false-positive rate nor evidence of which comparator released code uses. Image controls and their verdict basis also differ, so text-mode specificity cannot simply transfer to images.</p><p>Repository documentation is another versioned evidence surface. The current README distinguishes the live default detection ladder from a frozen calibrated detector, and sample smoke checks from full evaluation. The dataset card also discloses an older attack that wrote to a dead key never consumed by the action, later repaired by targeting a key that reaches arguments. That correction makes tracing a value into an actual action essential; finding a hostile string somewhere in the ledger is insufficient. <a href="https://github.com/SalesforceAIResearch/ErosionBench" target="_blank" rel="noreferrer">Current repository</a>, <a href="https://raw.githubusercontent.com/SalesforceAIResearch/ErosionBench/main/DATASET_CARD.md" target="_blank" rel="noreferrer">dataset-card changelog</a></p><h2 id="give-each-evidence-obligation-an-owner" tabindex="-1">Give each evidence obligation an owner <a class="header-anchor" href="#give-each-evidence-obligation-an-owner" aria-label="Permalink to &quot;Give each evidence obligation an owner&quot;">​</a></h2><p>For shared-context systems, we propose the following responsibility table. It is a checking method, not a common implemented pipeline attributed to the projects above.</p><table tabindex="0"><thead><tr><th>Obligation</th><th>Input and owner</th><th>Evidence to retain</th><th>When to stop inferring</th></tr></thead><tbody><tr><td>State visibility</td><td>Storage/synchronization receives a commit or write</td><td>Version actually read by the executor</td><td>An unknown checkout is not assumed current</td></tr><tr><td>Attribution</td><td>Trusted recording layer receives a write event</td><td>Traceable key, value and writer relationship</td><td>Missing history remains unknown</td></tr><tr><td>Key scope</td><td>Permission implementation receives writer and key</td><td>Applicable allowed scope and decision</td><td>Registered identity does not substitute for scope</td></tr><tr><td>Authorized intent</td><td>Action-permission check receives target and arguments</td><td>Relationship to this permitted action</td><td>An in-scope value still needs a permitted purpose</td></tr><tr><td>Side-effect outcome</td><td>Execution layer receives an allow/deny decision</td><td>Denied action identity and whether effects occurred</td><td>Post-effect detection is not pre-effect prevention</td></tr></tbody></table><p>Follow the hostile plan URL through the chain. Pull records establish the executor’s version; history identifies its writer; scope rules determine whether that writer may edit a plan field. Action authorization still has to connect that URL to the permitted target. Native execution records must finally distinguish an action that never ran from one detected afterward. If a link is missing, retain that gap instead of making history answer for it.</p><h2 id="the-executable-path-remains-to-be-checked" tabindex="-1">The executable path remains to be checked <a class="header-anchor" href="#the-executable-path-remains-to-be-checked" aria-label="Permalink to &quot;The executable path remains to be checked&quot;">​</a></h2><p>The public evidence comes from Letta’s official documentation team and the Salesforce-led ErosionBench research team. These are independent authoring actors supporting storage contracts and a provenance model respectively, not independent attack/defense replications of one implementation. The five internal ledger controls and tied-threshold calculation provide logical comparisons only. Current documents are byte-pinned snapshots retrieved on 2026-11-18; the paper is v1. Mutable repository guidance is not fused into an execution result from that historical paper version.</p><p>History remains valuable for audit. This article found or reproduced no product permission defect. The next step is to bind a target implementation, permission rules, calibration material and matching execution traces to exact versions, then test normal, wrong-scope, hostile-value and missing-history paths. Only a link between a denial decision and an effect that did not occur can support a prevention claim. Until then, neither detection rates nor complete edit history can sign for that missing evidence.</p>',24))])}const b=n(c,[["render",l]]);export{y as __pageData,b as default};
